<?php $summary=SeoExpert::paymentSummary($lead);?>
<div class="card"><h3>Payment history</h3><p><strong><?=e($summary['status'])?></strong> · Net received <?=money($summary['net'])?> · Proposal / listed total <?=money($summary['due'])?> · Balance <?=money($summary['balance'])?></p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th><th>Update pending payment</th></tr></thead><tbody><?php foreach(rows('SELECT * FROM seo_expert_payments WHERE enquiry_id=? ORDER BY paid_on DESC,id DESC',[$lead['id']]) as $payment):?><tr><td><?=e($payment['paid_on'])?></td><td><?=e($payment['kind'])?></td><td><?=money((int)$payment['amount'])?></td><td><?=e($payment['method'])?></td><td><?=e($payment['reference'])?></td><td><?=e($payment['status'])?></td><td><?php if($payment['status']==='pending'):expert_form('payment_status',(int)$lead['id']);?><input type="hidden" name="payment_id" value="<?=$payment['id']?>"><?php select_field('payment_state','Payment Status',['paid'=>'Paid','failed'=>'Failed','cancelled'=>'Cancelled']);?><button class="button secondary">Update payment</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
